import { execFile } from 'node:child_process';
import { access, mkdir } from 'node:fs/promises';
import { resolve } from 'node:path';

const DEFAULT_MAX_BUFFER = 64 * 1024 * 1024;

export async function git(repoDir: string, args: string[], opts?: { maxBuffer?: number }): Promise<string> {
  return new Promise((resolvePromise, reject) => {
    execFile(
      'git',
      args,
      { cwd: repoDir, maxBuffer: opts?.maxBuffer ?? DEFAULT_MAX_BUFFER },
      (err, stdout, stderr) => {
        if (err) reject(new Error(stderr?.toString() || err.message));
        else resolvePromise(stdout.toString());
      },
    );
  });
}

function isRemoteUrl(repoUrlOrPath: string): boolean {
  return /^(https?:\/\/|git@|ssh:\/\/)/.test(repoUrlOrPath);
}

function repoDirName(repoUrlOrPath: string): string {
  const cleaned = repoUrlOrPath.replace(/\.git$/, '');
  const parts = cleaned.split(/[/:]/).filter(Boolean);
  return parts.slice(-2).join('__');
}

async function pathExists(path: string): Promise<boolean> {
  return access(path).then(() => true, () => false);
}

/** Clones a URL under `<dataDir>/repos/<owner>__<name>` (or fetches if already cloned); a local path is used in place. */
export async function cloneOrUpdate(repoUrlOrPath: string, dataDir: string): Promise<string> {
  if (!isRemoteUrl(repoUrlOrPath)) return resolve(repoUrlOrPath);

  const reposDir = resolve(dataDir, 'repos');
  await mkdir(reposDir, { recursive: true });
  const repoDir = resolve(reposDir, repoDirName(repoUrlOrPath));

  if (await pathExists(repoDir)) {
    await git(repoDir, ['fetch', 'origin']).catch(() => undefined);
  } else {
    await new Promise<void>((resolvePromise, reject) => {
      execFile(
        'git',
        ['clone', '--filter=blob:none', repoUrlOrPath, repoDir],
        { cwd: reposDir, maxBuffer: DEFAULT_MAX_BUFFER },
        (err) => (err ? reject(err) : resolvePromise()),
      );
    });
  }

  await git(repoDir, ['fetch', 'origin', '+refs/entire/*:refs/entire/*']).catch(() => undefined);
  await git(repoDir, ['fetch', 'origin', '+refs/heads/entire/*:refs/remotes/origin/entire/*']).catch(() => undefined);

  return repoDir;
}

const MAX_DIFF_FILES = 40;
const MAX_PATCH_CHARS = 6000;

/** Returns the patch text for every file changed by `sha`, keyed by path, each capped at 6000 characters. */
export async function getDiff(repoDir: string, sha: string): Promise<Record<string, string>> {
  let out: string;
  try {
    out = await git(repoDir, ['diff-tree', '-p', '--no-color', '--no-commit-id', '--root', sha]);
  } catch {
    return {};
  }

  const result: Record<string, string> = {};
  const chunks = out.split(/(?=^diff --git )/m).filter((c) => c.startsWith('diff --git'));
  for (const chunk of chunks.slice(0, MAX_DIFF_FILES)) {
    const headerMatch = /^diff --git a\/(.+?) b\/(.+?)$/m.exec(chunk);
    const path = headerMatch?.[2];
    if (!path) continue;
    result[path] = chunk.slice(0, MAX_PATCH_CHARS);
  }
  return result;
}

import type { IngestArtifact, Session } from '@dailies/core';
import { listCheckpointRefs, readCheckpointSessions, type CheckpointRef } from './checkpoints';
import { cloneOrUpdate, getDiff, git } from './git';
import { mapCheckpointCommits } from './trailers';
import { parseTranscript } from './transcript';
import { mergeSessions, selectWindow } from './window';

export { git, cloneOrUpdate, getDiff } from './git';
export { listCheckpointRefs } from './checkpoints';
export type { CheckpointRef } from './checkpoints';
export { parseTranscript } from './transcript';
export { mapCheckpointCommits } from './trailers';

const DEFAULT_MAX_SESSIONS = 12;

export class NoCheckpointsError extends Error {}

async function buildSessionsForCheckpoint(repoDir: string, ref: CheckpointRef, commits: string[]): Promise<{ sessions: Session[]; redactions: number }> {
  const raw = await readCheckpointSessions(repoDir, ref);
  const sessions: Session[] = [];
  let redactions = 0;

  for (const r of raw) {
    const { entries, redactions: hits } = parseTranscript(r.sessionId, r.transcriptJsonl);
    redactions += hits;
    const startedAt = entries[0]?.ts ?? r.createdAt;
    const endedAt = entries.length > 0 ? entries[entries.length - 1]!.ts : null;
    sessions.push({
      id: r.sessionId,
      checkpointIds: [ref.id],
      agent: r.agent,
      model: r.model,
      branch: r.branch,
      startedAt,
      endedAt,
      turnCount: r.turnCount,
      tokens: r.tokens,
      commits,
      filesTouched: r.filesTouched,
      entries,
    });
  }

  return { sessions, redactions };
}

/** Reads a repository's Entire checkpoints into normalized sessions for the given window. */
export async function ingest(opts: {
  repoUrl: string;
  dataDir: string;
  since: string;
  until: string;
  maxSessions?: number;
}): Promise<IngestArtifact> {
  const repoDir = await cloneOrUpdate(opts.repoUrl, opts.dataDir);
  const refs = await listCheckpointRefs(repoDir);
  if (refs.length === 0) throw new NoCheckpointsError(`no checkpoint refs found in ${opts.repoUrl}`);

  const commitMap = await mapCheckpointCommits(repoDir);
  const skipped: { ref: string; reason: string }[] = [];
  let allSessions: Session[] = [];
  let redactions = 0;

  for (const ref of refs) {
    try {
      const commits = commitMap.get(ref.id) ?? [];
      const built = await buildSessionsForCheckpoint(repoDir, ref, commits);
      allSessions = allSessions.concat(built.sessions);
      redactions += built.redactions;
    } catch (err) {
      skipped.push({ ref: ref.treeish, reason: err instanceof Error ? err.message : String(err) });
    }
  }

  const merged = mergeSessions(allSessions);
  const windowed = selectWindow(merged, opts.since, opts.until, opts.maxSessions ?? DEFAULT_MAX_SESSIONS);

  const commitShas = Array.from(new Set(windowed.flatMap((s) => s.commits)));
  const diffs: Record<string, string> = {};
  for (const sha of commitShas) {
    const fileDiffs = await getDiff(repoDir, sha);
    for (const [path, patch] of Object.entries(fileDiffs)) diffs[`${sha}:${path}`] = patch;
  }

  const headSha = await git(repoDir, ['rev-parse', 'HEAD']).then((s) => s.trim()).catch(() => '');

  return {
    repo: { url: opts.repoUrl, dir: repoDir, headSha },
    sessions: windowed,
    diffs,
    skipped,
    enrichments: {},
    redactions,
  };
}

