1	import { redact, type IngestArtifact, type Session } from '@dailies/core';
2	import { listCheckpointRefs, readCheckpointSessions, type CheckpointRef } from './checkpoints';
3	import { cloneOrUpdate, getDiff, git } from './git';
4	import { mapCheckpointCommits } from './trailers';
5	import { parseTranscript } from './transcript';
6	import { mergeSessions, selectWindow } from './window';
7	
8	export { git, cloneOrUpdate, getDiff } from './git';
9	export { listCheckpointRefs } from './checkpoints';
10	export type { CheckpointRef } from './checkpoints';
11	export { parseTranscript } from './transcript';
12	export { mapCheckpointCommits } from './trailers';
13	
14	const DEFAULT_MAX_SESSIONS = 12;
15	
16	export class NoCheckpointsError extends Error {}
17	
18	async function buildSessionsForCheckpoint(repoDir: string, ref: CheckpointRef, commits: string[]): Promise<{ sessions: Session[]; redactions: number }> {
19	  const raw = await readCheckpointSessions(repoDir, ref);
20	  const sessions: Session[] = [];
21	  let redactions = 0;
22	
23	  for (const r of raw) {
24	    const { entries, redactions: hits } = parseTranscript(r.sessionId, r.transcriptJsonl);
25	    redactions += hits;
26	    const startedAt = entries[0]?.ts ?? r.createdAt;
27	    const endedAt = entries.length > 0 ? entries[entries.length - 1]!.ts : null;
28	    sessions.push({
29	      id: r.sessionId,
30	      checkpointIds: [ref.id],
31	      agent: r.agent,
32	      model: r.model,
33	      branch: r.branch,
34	      startedAt,
35	      endedAt,
36	      turnCount: r.turnCount,
37	      tokens: r.tokens,
38	      commits,
39	      filesTouched: r.filesTouched,
40	      entries,
41	    });
42	  }
